<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)msp2Redirect('garantias/index.php');$resumen=null;$movimientos=[];$error=null;
try{$s=$conn->prepare('SELECT * FROM dbo.msp_vw_garantias_control_integral WHERE id_garantia=:id');$s->execute([':id'=>(int)$id]);$resumen=$s->fetch();if(!$resumen)throw new RuntimeException('La garantía no existe.');$h=$conn->prepare('SELECT * FROM dbo.msp_vw_garantia_historial_integral WHERE id_garantia=:id ORDER BY fecha,id_origen');$h->execute([':id'=>(int)$id]);$movimientos=$h->fetchAll()?:[];}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'No fue posible cargar la ficha.';}function gfMonto(mixed $v):string{return '$ '.number_format((float)$v,0,',','.');}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ficha de garantía | MSP</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css"><link rel="stylesheet" href="/portalgp/styles.css"></head><body class="gp-layout bg-light"><?php include dirname(__DIR__,2).'/templates/header.php';?><main class="gp-main container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between mb-3"><div><p class="text-muted mb-1">MSP / Garantías</p><h1 class="h3">Ficha integral de garantía #<?php echo (int)$id;?></h1><?php if($resumen):?><p class="text-muted mb-0"><?php echo msp2Escape((string)$resumen['nombre_locatario']);?> · Contrato #<?php echo (int)$resumen['id_contrato_arriendo'];?> · Local <?php echo msp2Escape((string)$resumen['cdo_local']);?></p><?php endif;?></div><a class="btn btn-outline-dark btn-sm align-self-start" href="<?php echo msp2Escape(msp2Url('garantias/index.php'));?>">Volver a Garantías</a></div><?php if($error):?><div class="alert alert-danger"><?php echo msp2Escape($error);?></div><?php elseif($resumen):?><div class="row g-3 mb-4"><?php foreach(['monto_pactado'=>'Pactada','monto_recibido'=>'Recibida','monto_reservado'=>'Reservada','monto_aplicado'=>'Aplicada a deudas','monto_devuelto'=>'Devuelta','monto_disponible'=>'Disponible'] as $k=>$label):?><div class="col-6 col-lg-2"><div class="card shadow-sm h-100"><div class="card-body"><div class="small text-muted"><?php echo $label;?></div><div class="h5 mb-0"><?php echo gfMonto($resumen[$k]);?></div></div></div></div><?php endforeach;?></div><div class="card shadow-sm"><div class="card-header fw-semibold">Historial relacionado</div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Fecha</th><th>Operación</th><th>Concepto</th><th>Medio / cuenta</th><th>Referencia</th><th>Documento o cargo</th><th>Estado</th><th class="text-end">Monto</th></tr></thead><tbody><?php if($movimientos===[]):?><tr><td colspan="8" class="text-center text-muted py-4">Sin movimientos.</td></tr><?php endif;foreach($movimientos as $m):?><tr><td><?php echo msp2Escape(substr((string)$m['fecha'],0,10));?></td><td><?php echo msp2Escape((string)$m['tipo']);?></td><td><?php echo msp2Escape((string)$m['concepto']);?><div class="small text-muted"><?php echo msp2Escape((string)($m['observaciones']??''));?></div></td><td><?php echo msp2Escape((string)($m['medio']??'-'));?><div class="small text-muted"><?php echo msp2Escape((string)($m['cuenta']??''));?></div></td><td><?php echo msp2Escape((string)($m['referencia']??'-'));?></td><td><?php echo $m['id_documento']?'Documento #'.(int)$m['id_documento']:($m['id_cargo']?'Cargo #'.(int)$m['id_cargo']:'-');?></td><td><?php echo msp2Escape((string)$m['estado']);?></td><td class="text-end fw-semibold <?php echo $m['signo']==='+'?'text-success':'text-danger';?>"><?php echo msp2Escape((string)$m['signo']);?> <?php echo gfMonto($m['monto']);?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?></main></body></html>
